const {test}=require('node:test'),assert=require('node:assert/strict'),T=require('../src/catalog.js'),M=require('../src/model.js');
test('catálogo tem uma origem, 800 passivas e todas estão conectadas',()=>{assert.equal(T.nodes.length,801);assert.equal(T.nodes.filter(n=>n.type==='origin').length,1);assert.equal(T.index.get('root').title,'Guardião');assert.equal(new Set(T.nodes.map(n=>n.id)).size,801);assert.equal(M.connected(T.nodes.map(n=>n.id)),true);for(const f of T.families)assert.equal(T.nodes.filter(n=>n.family===f.key&&n.id!=='root').length,100);for(const n of T.nodes)assert.ok(Number.isFinite(n.x)&&Number.isFinite(n.y));});
test('cada ponto de habilidade tem nome, bônus válido e descrição correspondente',()=>{for(const n of T.nodes.filter(n=>n.id!=='root')){assert.ok(n.title);assert.ok(Object.keys(n.mods).length);for(const[k,v]of Object.entries(n.mods)){assert.ok(T.MODS[k]);assert.ok(Number.isFinite(v)&&v!==0);}assert.equal(T.lines(n).length,Object.keys(n.mods).length);}assert.deepEqual(T.lines(T.index.get('cluster_2_0_notable')),['Regeneração de mana aumentada em 25%']);assert.equal(T.nodes.filter(n=>n.type==='keystone').length,8);for(const n of T.nodes.filter(n=>n.type==='keystone'))assert.ok(Object.values(n.mods).some(v=>v<0));});
test('conexões são únicas e simétricas e não têm referências órfãs',()=>{const seen=new Set();for(const[a,b]of T.edges){assert.ok(T.index.has(a)&&T.index.has(b));assert.notEqual(a,b);assert.ok(T.index.get(a).neighbors.includes(b));assert.ok(T.index.get(b).neighbors.includes(a));const key=[a,b].sort().join('|');assert.ok(!seen.has(key));seen.add(key);}});
test('nível um não aloca pontos e nível 99 admite somente 98',()=>{const ids=new Set();assert.ok(M.valid(ids,1));assert.equal(M.addPath(ids,['road_0_1'],1),null);assert.equal(M.budget(99),98);const queue=['root'],owned=new Set();for(let i=0;i<queue.length&&owned.size<98;i++)for(const n of T.index.get(queue[i]).neighbors)if(n!=='root'&&!owned.has(n)&&owned.size<98){owned.add(n);queue.push(n);}assert.ok(M.valid(owned,99));const candidate=T.nodes.find(n=>n.id!=='root'&&!owned.has(n.id)&&n.neighbors.some(k=>owned.has(k)));assert.equal(M.addPath(owned,[candidate.id],99),null);assert.ok(!M.valid(owned,98));});
test('caminho mínimo começa no que já foi escolhido e não gasta parcialmente',()=>{const ids=new Set(['road_0_1','road_0_2']),target='keystone_0',path=M.pathTo(ids,target);assert.ok(path.length>1);const before=[...ids];assert.equal(M.addPath(ids,path,2),null);assert.deepEqual([...ids],before);const result=M.addPath(ids,path,99);assert.ok(result.has(target));assert.ok(M.connected(result));assert.equal(result.size,ids.size+path.length);assert.deepEqual(M.pathTo(result,target),[]);assert.equal(M.addPath(ids,['road_0_15'],99),null);assert.equal(M.addPath(ids,['road_0_1'],99),null);});
test('remoção preserva a conexão e pode usar rotas alternativas',()=>{const ids=new Set(['road_0_1','road_0_2','road_0_3']);assert.equal(M.remove(ids,'road_0_1',10),null);assert.ok(M.remove(ids,'road_0_3',10));const both=new Set();const a=M.addPath(both,M.pathTo(both,'road_1_3'),99);const b=M.addPath(a,M.pathTo(a,'road_0_3'),99);const c=M.addPath(b,['bridge_0_0_1','bridge_0_0_2','bridge_0_0_3','bridge_0_0_4'],99);assert.ok(c);assert.ok(M.remove(c,'road_0_2',99));});
test('resumo soma valores, percentuais, pontos percentuais e penalidades',()=>{const ids=new Set(['road_0_1','road_0_2','keystone_0','cluster_2_0_notable','cluster_4_0_notable']);const sum=M.totals(ids);assert.equal(sum.strength,4);assert.equal(sum.physicalDefense,30);assert.equal(sum.moveSpeed,-10);assert.equal(sum.manaRegen,25);assert.equal(sum.critChance,2);});
test('importação rejeita pontos duplicados, desconhecidos, desconectados e nível inválido',()=>{for(const raw of [{},{version:2,level:3,nodes:[]},{version:1,level:100,nodes:[]},{version:1,level:2,nodes:['road_0_1','road_0_1']},{version:1,level:99,nodes:['fake']},{version:1,level:99,nodes:['keystone_0']},{version:1,level:1,nodes:['road_0_1']}])assert.throws(()=>M.validateSave(raw));const saved=M.snapshot(7,new Set(['road_0_1','road_0_2'])),loaded=M.validateSave(JSON.parse(JSON.stringify(saved)));assert.equal(loaded.level,7);assert.deepEqual([...loaded.nodes],saved.nodes);});
test('busca ignora acentos e pode filtrar afinidade e descrições',()=>{assert.ok(M.search('mente aberta').has('cluster_2_0_notable'));assert.ok(M.search('regeneracao de mana').has('cluster_2_0_notable'));assert.equal(M.search('regeneracao de mana','might').size,0);assert.ok([...M.search('critico','precision')].every(id=>T.index.get(id).family==='precision'));});
